from pathlib import Path
from html import escape
import json
out=Path('verification/follow-up-20261016')
shots=[('home','Home'),('home-notes','Home Notes'),('notes-english','Notes'),('blog','Blog publication dates'),('blog-reading','Blog reading page'),('repair-video','Repair video'),('balances-cards','Service cards'),('notes-cards-detail','Four service Notes cards'),('state-arkansas','Arkansas flag header'),('state-connecticut','Connecticut sources'),('bookkeeping-chatsworth','City heading'),('index-es','Centered Spanish notice'),('index-fa','Persian layout')]
html='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="robots" content="noindex,nofollow"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Paper Trail, corrections review</title><style>body{font:16px/1.6 Arial,sans-serif;color:#202020;background:#f3f3f3;margin:0}main{max-width:1200px;margin:auto;padding:30px}h1{font-size:32px}nav{display:flex;gap:16px;flex-wrap:wrap}a{color:inherit;text-underline-offset:4px}button{padding:12px 20px;border:1px solid;background:#fff;cursor:pointer;font:inherit}button[aria-pressed=true]{background:#202020;color:white}.gallery{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:24px}figure{margin:0;background:#fff;padding:16px;border:1px solid #ccc}img{display:block;width:100%;height:auto}figcaption{font-weight:bold;margin-bottom:12px}.mobile img{max-width:390px;margin:auto}.tablet img{max-width:834px}section{margin-block:30px}.muted{font-size:14px;color:#505050}@media(max-width:750px){.gallery{grid-template-columns:1fr}}</style></head><body><main><h1>Paper Trail, corrections review</h1><nav><a href="../../index.html">Open Home</a><a href="../../blog.html">Open Blog</a><a href="../../notes.html">Open Notes</a><a href="../../nationwide-bookkeeping.html">Open Nationwide</a></nav><p>Centered language notices and Notes text, single question chat flow, corrected city headings and button labels, state flag headers, and Blog dates supplied by the owner. The original media assets, brand colors, integrations, and menu design are preserved.</p><p id="results">192 pages checked at three sizes, 576 page and device checks. All 60 language checks retained menu and selector positions. Forty two cold loads recorded zero layout shift, including direct file previews. No overflow, missing images, or JavaScript exceptions were observed.</p><p class="muted">State pages remain local drafts, noindex and outside the published sitemap. Individual factual approval is still required. Prior source checks have 51 automated access limitations. No inquiries, Google API requests, commits, pushes, or publication were performed.</p><section><nav aria-label="Screenshot size"><button aria-pressed="true" data-size="1440">Desktop</button><button aria-pressed="false" data-size="834">iPad</button><button aria-pressed="false" data-size="390">Mobile</button></nav></section><div class="gallery">'''
for name,label in shots:
 html+='<figure><figcaption>'+escape(label)+'</figcaption><a data-shot="'+name+'" href="screenshots/'+name+'-1440.png"><img loading="lazy" data-shot="'+name+'" src="screenshots/'+name+'-1440.png" alt="'+escape(label)+' screenshot"></a></figure>'
html+='''</div><section><h2>Chat and phone</h2><div class="gallery"><figure><figcaption>One active question, previous answers retained</figcaption><img src="screenshots/chat-desktop.png" alt="Chat question flow"></figure><figure><figcaption>Desktop call options</figcaption><img src="screenshots/phone-desktop.png" alt="Phone options"></figure></div></section><section><h2>Before this correction pass</h2><p>These are the earlier saved screenshots for comparison.</p><div class="gallery">'''
for name,label in [('home-notes-390','Previous mobile Notes text'),('notes-english-390','Previous Notes icon placement'),('state-arkansas-1440','Previous state header'),('blog-1440','Previous Blog dates')]:
 html+='<figure><figcaption>'+label+'</figcaption><img loading="lazy" src="../visual-corrections/screenshots/'+name+'.png" alt="'+label+'"></figure>'
html+='''</div></section><script>document.querySelectorAll('[data-size]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-size]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));const width=b.dataset.size;document.querySelector('.gallery').className='gallery '+(width==='390'?'mobile':width==='834'?'tablet':'desktop');document.querySelectorAll('[data-shot]').forEach(e=>e[e.tagName==='IMG'?'src':'href']='screenshots/'+e.dataset.shot+'-'+width+'.png')})</script></main></body></html>'''
(out/'review.html').write_text(html,encoding='utf-8')
# Keep the previously shared review URL useful and current.
Path('verification/visual-corrections/review.html').write_text(html.replace('<head>','<head><base href="../follow-up-20261016/">'),encoding='utf-8')
print('Review created')
